  function tbsa(ids) { var tot = 0; BURN.NINES.forEach(function (p) { if (ids.indexOf(p[0]) >= 0) tot += p[2]; }); return tot; }
  function parkland(kg, pct, hrs) {
    hrs = hrs || 0; var total = 4 * kg * pct, half = total / 2, left = Math.max(0, 8 - hrs);
    return { total: total, half: half, left: left, rate8: Math.round(half / 8), rate1: left > 0 ? Math.round(half / left) : 0, rate2: Math.round(half / 16), uo: Math.round(kg * 0.5) };
  }
